extern "C" {

void unpack_addr(int32_t *restrict in, int32_t *restrict out) {
  int8_t *bp = (int8_t *)(in + REGION_WORD) + 1024;
  bool sgn = in[0];
  int form = in[1];
  event0();
  if (form == 0)
    form0(bp, in + HEADER, sgn, out);
  else if (form == 1)
    form1(bp, in + HEADER, sgn, out);
  else if (form == 2)
    form2(bp, in + HEADER, sgn, out);
  else
    form3(bp, in + HEADER, sgn, out);
  event1();
}

} // extern "C"
